open(p,'a').write('''
/** Points the org at a new recorded owner. */
export async function setOrgOwner(
  orgId: OrgId,
  ownerId: UserId,
): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set({ ownerId, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

function toHandover(row: OwnershipHandoverRow): OwnershipHandover {
  return {
    id: row.id,
    orgId: row.orgId as OrgId,
    fromUserId: row.fromUserId as UserId,
    toUserId: row.toUserId as UserId,
    status: row.status,
    expiresAt: row.expiresAt as IsoTimestamp,
    createdAt: row.createdAt as IsoTimestamp,
    resolvedAt: (row.resolvedAt as IsoTimestamp | null) ?? null,
  };
}

/** The row still marked `pending`; the caller decides whether it has lapsed. */
export async function findPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending")),
    )
    .get();
  return row ? toHandover(row) : null;
}

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  createdAt: Date,
  expiresAt: Date,
): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt: toIsoTimestamp(expiresAt),
      createdAt: toIsoTimestamp(createdAt),
      resolvedAt: null,
    })
    .returning()
    .get();
  return toHandover(row);
}

export async function resolveHandover(
  orgId: OrgId,
  handoverId: string,
  status: OwnershipHandoverStatus,
  resolvedAt: Date,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt: toIsoTimestamp(resolvedAt) })
    .where(
      and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.id, handoverId)),
    )
    .returning()
    .get();
  if (!row) throw new Error(`Ownership handover ${handoverId} not found`);
  return toHandover(row);
}

/** Withdraws the open offer when either side of it leaves the workspace. */
export async function cancelPendingHandoversInvolving(
  orgId: OrgId,
  userId: UserId,
  resolvedAt: Date,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: toIsoTimestamp(resolvedAt) })
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}
''')

