/** An offer lapses exactly seven days after it was made. */
const HANDOVER_TTL_MS = 7 * 24 * 60 * 60 * 1000;

function hasLapsed(handover: OwnershipHandover, now: Date): boolean {
  return now.getTime() >= Date.parse(handover.expiresAt);
}

/** Holding the owner role is not enough: only the recorded owner may do this. */
function assertRecordedOwner(
  actor: Actor,
  org: Organization,
  action: "org:update",
): void {
  if (org.ownerId === actor.userId) return;
  throw new PermissionDeniedError(action, {
    action,
    resourceKind: "organization",
    allowed: false,
    reason: "denied_by_role",
  });
}

async function loadOrg(orgId: OrgId): Promise<Organization> {
  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

/** The offer the actor may act on as the offered member, or a refusal. */
async function requireOfferedTo(actor: Actor, orgId: OrgId, now: Date) {
  const pending = await orgRepo.findPendingHandover(orgId);
  if (pending === null || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (hasLapsed(pending, now)) throw new OwnershipHandoverError("expired");
  return pending;
}

export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = await loadOrg(orgId);
  assertRecordedOwner(actor, org, "org:update");

  if (toUserId === org.ownerId) throw new OwnershipHandoverError("self");

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const open = await orgRepo.findPendingHandover(orgId);
  if (open !== null) {
    if (!hasLapsed(open, now)) throw new OwnershipHandoverError("pending_exists");
    await orgRepo.resolveHandover(orgId, open.id, "expired", now);
  }

  const handover = await orgRepo.insertHandover(
    orgId,
    org.ownerId,
    toUserId,
    now,
    new Date(now.getTime() + HANDOVER_TTL_MS),
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Workspace ownership offered",
    body: `${actor.userId} offered you ownership of ${org.name}`,
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const now = new Date();
  const pending = await requireOfferedTo(actor, orgId, now);

  const incoming = requireFound(
    await memberRepo.findMember(orgId, pending.toUserId),
    "Member",
    pending.toUserId,
  );
  const outgoing = await memberRepo.findMember(orgId, pending.fromUserId);

  // The incoming owner is promoted first so the workspace always has an owner.
  if (incoming.role !== "owner") {
    const promoted = await memberRepo.updateMemberRole(orgId, incoming.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: promoted.id,
      from: incoming.role,
      to: promoted.role,
    });
  }

  const org = await orgRepo.setOrgOwner(orgId, pending.toUserId);

  if (outgoing && outgoing.role === "owner") {
    const demoted = await memberRepo.updateMemberRole(orgId, outgoing.id, "admin");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: demoted.id,
      from: outgoing.role,
      to: demoted.role,
    });
  }

  await orgRepo.resolveHandover(orgId, pending.id, "accepted", now);

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: pending.fromUserId,
    toUserId: pending.toUserId,
  });

  return org;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const now = new Date();
  const pending = await requireOfferedTo(actor, orgId, now);
  return orgRepo.resolveHandover(orgId, pending.id, "declined", now);
}

export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = await loadOrg(orgId);
  assertRecordedOwner(actor, org, "org:update");

  const now = new Date();
  const pending = await orgRepo.findPendingHandover(orgId);
  if (pending === null || hasLapsed(pending, now)) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  return orgRepo.resolveHandover(orgId, pending.id, "canceled", now);
}

export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const pending = await orgRepo.findPendingHandover(orgId);
  if (pending === null || hasLapsed(pending, new Date())) return null;
  return pending;
}
